using System.Reflection;
using System.Runtime.InteropServices;
using OcctSharp.CopiedCollections;
using OcctSharp.ModelingWorkspaces;
using OcctSharp.Values;
namespace OcctSharp.Runtime.Tests;
public sealed class ModelingBuildersTests {
 [Fact]public void FullBuildAnalysisRepairAndRealFiles()=>OcctSharp.Tests.Shared.BatchAPModelingWorkflow.Run();
 [Fact]public void IdenticalPointsPublishOnlyFailureDiagnostics(){using var result=ModelingBuilders.Edge(new(1,2,3),new(1,2,3));Assert.False(result.IsDone);Assert.NotEqual(0,result.Error);Assert.Throws<InvalidOperationException>(()=>result.Shape);}
 [Fact]public void EmptyAndDisconnectedWiresNeverPublishPartialTopology(){using var empty=OwnedShapeSet.Create();using var result=ModelingBuilders.Wire(empty);Assert.False(result.IsDone);Assert.NotEqual(0,result.Error);Assert.Throws<InvalidOperationException>(()=>result.Shape);using var a=ModelingBuilders.Edge(new(0,0,0),new(1,0,0));using var b=ModelingBuilders.Edge(new(8,0,0),new(9,0,0));using var first=a.Shape;using var second=b.Shape;using var set=OwnedShapeSet.Create(first,second);using var disconnected=ModelingBuilders.Wire(set);Assert.False(disconnected.IsDone);Assert.Throws<InvalidOperationException>(()=>disconnected.Shape);Assert.Equal(1,first.CountSubShapes(ShapeKind.Edge));}
 [Fact]public void PrivateCurveAndResultsSurviveSourceDisposal(){using var surface=GeomBSplineSurfaceCollections.Create(new([new Coordinates3d(0,0,0),new(0,3,0),new(2,0,0),new(2,3,0)],2,2),new([0.0,1]),new([0.0,1]),new([2,2]),new([2,2]),1,1,false,false);using var curve=surface.UIso(.5)!;using var builder=ModelingBuilders.Edge(curve,0,1);using var edge=builder.Shape;curve.Dispose();surface.Dispose();builder.Dispose();Assert.True(edge.IsValid);Assert.Equal(3,edge.InspectProperties(InspectionPropertyKind.Length).Mass,7);}
 [Fact]public void RelatedTopologyIsCopiedAndOwnsItsLifetime(){using var builder=ModelingBuilders.Edge(new(0,0,0),new(2,0,0));using var a=builder.Shape;using var b=builder.Shape;using var first=builder.GetRelatedShape(1)!;using var last=builder.GetRelatedShape(2)!;Assert.False(a.IsSame(b));builder.Dispose();Assert.True(a.IsValid);Assert.Equal(1,first.CountSubShapes(ShapeKind.Vertex));Assert.Equal(1,last.CountSubShapes(ShapeKind.Vertex));}
 [Fact]public void CountsAreInitializedDetachedAndNotUniqueCounts(){using var box=ShapeFactory.CreateBox(2,3,4);using var result=ModelingBuilders.Contents(box);Assert.Equal(33,result.Counts.Count);Assert.Equal(1,result.Counts["NbSolids"]);Assert.Equal(6,result.Counts["NbFaces"]);Assert.True(result.Counts["NbEdges"]>=12);Assert.Equal(12,result.Counts["NbSharedEdges"]);using var group=result.GetGroup(0);Assert.Equal(0,group.Count);box.Dispose();result.Dispose();Assert.Equal(6,result.Counts["NbFaces"]);Assert.Equal(0,group.Count);Assert.IsType<System.Collections.ObjectModel.ReadOnlyDictionary<string,int>>(result.Counts);}
 [Fact]public void AllGroupsAndFlagsAreBounded(){using var box=ShapeFactory.CreateBox(1,1,1);using var result=ModelingBuilders.Contents(box,ShapeContentGroups.None);for(int i=0;i<6;++i){using var group=result.GetGroup(i);Assert.Equal(0,group.Count);}Assert.Throws<ArgumentOutOfRangeException>(()=>result.GetGroup(6));Assert.Throws<ArgumentException>(()=>ModelingBuilders.Contents(box,(ShapeContentGroups)64));}
 [Fact]public void FalseDiagnosticsDoNotInventPointOrNotchOutputs(){using var wire=ShapeFactory.CreatePolygonWire([new(0,0,0),new(2,0,0),new(2,2,0),new(0,2,0)],true);using var face=ShapeFactory.CreatePlanarFace(wire);var bounds=face.GetSubShapes(ShapeKind.Wire);try{var lacking=ModelingBuilders.CheckLacking(bounds[0],face,1);Assert.False(lacking.Found);Assert.Null(lacking.First);Assert.Null(lacking.Second);var notch=ModelingBuilders.CheckNotchedEdges(bounds[0],face,1);Assert.False(notch.Found);Assert.Null(notch.Parameter);Assert.Null(notch.ShortEdge);Assert.False(ModelingBuilders.CheckDegenerated(bounds[0],face,1).Found);}finally{foreach(var bound in bounds)bound.Dispose();}}
 [Fact]public void ForeignWireIndexAndNonfiniteInputsRejected(){using var wire=ShapeFactory.CreatePolygonWire([new(0,0,0),new(1,0,0),new(1,1,0)],true);using var face=ShapeFactory.CreatePlanarFace(wire);using var other=ShapeFactory.CreatePolygonWire([new(4,0,0),new(5,0,0),new(5,1,0)],true);Assert.Throws<ArgumentException>(()=>ModelingBuilders.CheckLacking(other,face,1));var bounds=face.GetSubShapes(ShapeKind.Wire);try{Assert.Throws<ArgumentException>(()=>ModelingBuilders.CheckDegenerated(bounds[0],face,0));Assert.Throws<ArgumentException>(()=>ModelingBuilders.CheckNotchedEdges(bounds[0],face,1,double.NaN));}finally{foreach(var bound in bounds)bound.Dispose();}Assert.Throws<ArgumentException>(()=>ModelingBuilders.Edge(new(double.NaN,0,0),new(1,0,0)));}
 [Fact]public void ConcurrentReadsAndReleaseUseLeasedStorage(){using var builder=ModelingBuilders.Edge(new(0,0,0),new(2,0,0));var errors=new System.Collections.Concurrent.ConcurrentQueue<Exception>();Parallel.For(0,80,i=>{try{if(i==20)builder.Dispose();else{using var shape=builder.Shape;Assert.True(shape.IsValid);}}catch(ObjectDisposedException){}catch(Exception e){errors.Enqueue(e);}});Assert.Empty(errors);Assert.Throws<ObjectDisposedException>(()=>builder.Shape);}
 [Fact]public void RealNotchPublishesBoundedCoupledOutputs(){using var wire=ShapeFactory.CreatePolygonWire([new(0,0,0),new(2,0,0),new(1,0,0),new(1,2,0),new(0,2,0)],true);using var face=ShapeFactory.CreatePlanarFace(wire);var bounds=face.GetSubShapes(ShapeKind.Wire);try{var hits=Enumerable.Range(1,5).Select(i=>ModelingBuilders.CheckNotchedEdges(bounds[0],face,i)).Where(x=>x.Found).ToArray();Assert.NotEmpty(hits);Assert.All(hits,x=>{Assert.InRange(x.ShortEdge!.Value,1,5);Assert.True(double.IsFinite(x.Parameter!.Value));});}finally{foreach(var bound in bounds)bound.Dispose();}}
 [Fact]public void FalseNativeFailureRetainsFailStatus(){using var wire=ShapeFactory.CreatePolygonWire([new(0,0,0),new(2,0,0),new(2,2,0),new(0,2,0)],true);using var face=ShapeFactory.CreatePlanarFace(wire);var vertices=face.GetSubShapes(ShapeKind.Vertex);try{using var bad=face.RemoveSubshape(vertices[0]);var bounds=bad.GetSubShapes(ShapeKind.Wire);try{var checks=Enumerable.Range(1,4).Select(i=>ModelingBuilders.CheckLacking(bounds[0],bad,i)).ToArray();Assert.Contains(checks,x=>!x.Found&&x.HasStatus(18));Assert.All(checks.Where(x=>!x.Found),x=>{Assert.Null(x.First);Assert.Null(x.Second);});}finally{foreach(var bound in bounds)bound.Dispose();}}finally{foreach(var vertex in vertices)vertex.Dispose();}}
 [UnmanagedFunctionPointer(CallingConvention.Cdecl)]delegate int RawShape(nint token,int role,out nint output);
 static nint Token(object value)=>((SafeHandle)value.GetType().GetField("handle",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(value)!).DangerousGetHandle();
 [UnmanagedFunctionPointer(CallingConvention.Cdecl)]unsafe delegate int RawContents(nint source,int flags,int* values,int capacity,out nint output);
 [Fact]public unsafe void RawCapacityRejectsBeforeWritingCounts(){using var box=ShapeFactory.CreateBox(1,1,1);nint library=NativeLibrary.Load(Path.Combine(AppContext.BaseDirectory,"occt","OcctSharp.Native.dll"));try{var create=Marshal.GetDelegateForFunctionPointer<RawContents>(NativeLibrary.GetExport(library,"occtsharp_modeling_contents_create"));int sentinel=123;Assert.NotEqual(0,create(Token(box),63,&sentinel,1,out var result));Assert.Equal(0,result);Assert.Equal(123,sentinel);Assert.NotEqual(0,create(Token(box),63,null,33,out result));Assert.Equal(0,result);}finally{NativeLibrary.Free(library);}}
 [Fact]public void WrongTypedAndReleasedTokensPublishNothing(){using var box=ShapeFactory.CreateBox(1,1,1);using var contents=ModelingBuilders.Contents(box);using var builder=ModelingBuilders.Edge(new(0,0,0),new(2,0,0));nint library=NativeLibrary.Load(Path.Combine(AppContext.BaseDirectory,"occt","OcctSharp.Native.dll"));try{var get=Marshal.GetDelegateForFunctionPointer<RawShape>(NativeLibrary.GetExport(library,"occtsharp_modeling_builder_shape"));Assert.NotEqual(0,get(Token(contents),0,out var output));Assert.Equal(0,output);Assert.NotEqual(0,get(Token(builder),99,out output));Assert.Equal(0,output);var token=Token(builder);builder.Dispose();Assert.NotEqual(0,get(token,0,out output));Assert.Equal(0,output);}finally{NativeLibrary.Free(library);}}
}
